import taxonomyData from "@/storefront/data/taxonomy.json";

/**
 * Category taxonomy — DATA-DRIVEN from the migration catalogue (src/storefront/
 * data/taxonomy.json, regenerated by scripts/tokyo-export-catalog.ts from the real
 * DB category tree). This replaces the former hand-curated Tokyo-Store-UI taxonomy:
 * the owner's rule is to take the categories from the migration data and use them.
 * Every node carries its REAL slug (disambiguated where the DB disambiguates, e.g.
 * son-accessoires-telephoniques), so nav links and breadcrumbs always resolve.
 */
export type TaxoNode = { slug: string; name: string; count: number; children: TaxoNode[] };
export type NavCrumb = { label: string; slug: string };
export type NavContext = {
  /** Root universe of the slug (undefined for an unknown slug). */
  universe?: NavCrumb;
  /** The level-2 section the slug sits under (undefined for a universe or a section itself). */
  section?: NavCrumb;
  /** Drill-down rail: the node's children, or its siblings when it's a leaf. */
  siblings: NavCrumb[];
  /** True when the slug is a top-level universe. */
  isUniverse: boolean;
};

export const taxonomy = taxonomyData as TaxoNode[];

const nodeBySlug = new Map<string, TaxoNode>();
const parentBySlug = new Map<string, string | null>();
const chainBySlug = new Map<string, TaxoNode[]>();
(function index(nodes: TaxoNode[], parent: string | null, chain: TaxoNode[]) {
  for (const n of nodes) {
    const here = [...chain, n];
    nodeBySlug.set(n.slug, n);
    parentBySlug.set(n.slug, parent);
    chainBySlug.set(n.slug, here);
    index(n.children, n.slug, here);
  }
})(taxonomy, null, []);

const toCrumb = (n: TaxoNode): NavCrumb => ({ label: n.name, slug: n.slug });

/** Every universe as a quick link (fallback nav rail). */
export const universeCrumbs: NavCrumb[] = taxonomy.map(toCrumb);

/** Resolve where a category slug sits in the taxonomy. */
export function getNavContext(slug: string): NavContext {
  const chain = chainBySlug.get(slug);
  if (!chain || chain.length === 0) return { siblings: [], isUniverse: false };
  const node = chain[chain.length - 1];
  const isUniverse = chain.length === 1;
  const section = chain.length >= 2 ? chain[1] : undefined;
  // Drill INTO children when the node has them, otherwise show its siblings (its
  // parent's children), falling back to the universes for an orphan.
  let siblings: NavCrumb[];
  if (node.children.length > 0) {
    siblings = node.children.map(toCrumb);
  } else {
    const parentSlug = parentBySlug.get(slug);
    const parent = parentSlug ? nodeBySlug.get(parentSlug) : undefined;
    siblings = parent ? parent.children.map(toCrumb) : taxonomy.map(toCrumb);
  }
  return {
    universe: toCrumb(chain[0]),
    section: section && section.slug !== node.slug ? toCrumb(section) : undefined,
    siblings,
    isUniverse,
  };
}

/** The trail between "Accueil" and a page: its ancestors (root→parent), never the page itself. */
export function categoryTrail(slug: string): NavCrumb[] {
  const chain = chainBySlug.get(slug);
  if (!chain) return [];
  return chain.slice(0, -1).map(toCrumb);
}

/** The taxonomy's display label for a slug (the migration category name), if known. */
export function taxonomyLabel(slug: string): string | undefined {
  return nodeBySlug.get(slug)?.name;
}
